// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"General chemistry begins with what matter is made of and how chemists count particles.","blocks":[{"t":"key","text":"Atoms contain protons (+), neutrons (0) and electrons (−). Atomic number Z = protons; mass number A = protons + neutrons. Isotopes differ in neutrons; atomic mass is a weighted average."},{"t":"p","text":"The mole: 1 mol = 6.022 × 10²³ particles (Avogadro's number). Molar mass (g/mol) converts grams to moles: n = m/M."},{"t":"p","text":"Formulas: percent composition, empirical formula (simplest ratio) and molecular formula (a whole-number multiple). Significant figures and dimensional analysis carry units through every calculation."},{"t":"ex","problem":"Find the moles in 9.0 g of water (M = 18.0 g/mol).","steps":["n = 9.0 ÷ 18.0"],"answer":"0.50 mol"}]},{"say":"Balanced equations tell us exactly how much reacts and how much forms.","blocks":[{"t":"key","text":"Balance equations by conserving atoms. Reaction types: precipitation (use solubility rules and net ionic equations), acid–base neutralization, redox and combustion."},{"t":"p","text":"Stoichiometry: grams → moles → mole ratio → moles → grams. The limiting reactant runs out first and sets the theoretical yield; percent yield = actual ÷ theoretical × 100%."},{"t":"p","text":"Solutions: molarity M = mol solute ÷ L solution. Dilution: M₁V₁ = M₂V₂. Titrations find unknown concentrations at the equivalence point."},{"t":"ex","problem":"How many moles of NaCl are in 250 mL of 0.40 M solution?","steps":["0.40 mol/L × 0.250 L"],"answer":"0.10 mol"},{"t":"lab","kind":"lab","title":"Serial dilution","aim":"Pipette different volumes of a 2.00 M stock solution into a 100.0 mL volumetric flask and fill to the mark.","sets":[{"name":"V1","start":10,"label":"Stock volume (mL)","min":1,"max":50,"step":1},{"name":"M1","start":2,"label":"Stock concentration (M)","min":0.5,"max":5,"step":0.5}],"outs":[{"name":"M2","expr":"M1*V1/100","label":"Diluted concentration (M)"},{"name":"n","expr":"M1*V1/1000","label":"Moles of solute (mol)"}],"steps":["Record the diluted concentration for 5 stock volumes.","What volume of stock makes exactly 0.150 M?"],"noise":1,"result":"Dilution adds solvent but not solute, so M₁V₁ = M₂V₂. To make 0.150 M from 2.00 M stock in a 100 mL flask, pipette 7.5 mL.","plot":{"x":"V1","y":"M2"}}]}],[{"say":"Gases follow simple laws, and every reaction comes with an energy change.","blocks":[{"t":"key","text":"Ideal gas law: PV = nRT (R = 0.08206 L·atm/(mol·K)). Combined laws: Boyle (P₁V₁ = P₂V₂), Charles (V₁/T₁ = V₂/T₂), Avogadro. Use kelvin. Dalton's law: total pressure is the sum of partial pressures. Kinetic molecular theory explains gas behavior; real gases deviate at high pressure and low temperature."},{"t":"p","text":"Thermochemistry: q = mcΔT. Exothermic ΔH < 0, endothermic ΔH > 0. Hess's law adds reaction enthalpies; ΔH°rxn = ΣΔH°f(products) − ΣΔH°f(reactants)."},{"t":"ex","problem":"A gas at 2.0 atm occupies 3.0 L. Find its volume at 1.0 atm (constant T).","steps":["P₁V₁ = P₂V₂: 2.0 × 3.0 = 1.0 × V₂"],"answer":"6.0 L"},{"t":"lab","kind":"lab","title":"Mixing hot and cold water","aim":"Mix hot water with 100 g of water at 20 °C in an insulated cup and record the final temperature.","sets":[{"name":"m1","start":100,"label":"Hot water mass (g)","min":10,"max":300,"step":10},{"name":"T1","start":80,"label":"Hot water temperature (°C)","min":30,"max":100,"step":5}],"outs":[{"name":"Tf","expr":"(m1*T1 + 100*20)/(m1 + 100)","label":"Final temperature (°C)"},{"name":"q","expr":"m1*4.18*(T1 - Tf)","label":"Heat lost by hot water (J)"}],"steps":["Record the final temperature for 5 masses of hot water.","Check that heat lost by the hot water equals heat gained by the cold water."],"noise":1,"result":"Energy is conserved: heat lost = heat gained (m₁cΔT₁ = m₂cΔT₂). The final temperature is a mass-weighted average, closer to whichever sample is larger.","plot":{"x":"m1","y":"Tf"}}]},{"say":"Electron arrangements explain the periodic table and how atoms bond.","blocks":[{"t":"key","text":"Quantum numbers (n, l, mₗ, mₛ) describe orbitals. Electron configurations follow Aufbau, Pauli and Hund (Fe: [Ar] 4s² 3d⁶). Periodic trends: atomic radius decreases across a period and increases down a group; ionization energy and electronegativity show the opposite pattern."},{"t":"p","text":"Bonding: ionic (electron transfer), covalent (sharing) and metallic. Lewis structures, formal charge and resonance. VSEPR predicts geometry: 2 domains linear, 3 trigonal planar, 4 tetrahedral (109.5°), with lone pairs giving bent or trigonal pyramidal shapes. Hybridization (sp, sp², sp³) and polarity follow."},{"t":"p","text":"Intermolecular forces: dispersion < dipole–dipole < hydrogen bonding; stronger forces raise boiling points."}]}],[{"say":"How fast does a reaction go, and how far? Kinetics and equilibrium answer.","blocks":[{"t":"key","text":"Rate laws: rate = k[A]ᵐ[B]ⁿ with orders found experimentally. Integrated rate laws: first-order half-life t½ = 0.693/k (constant). The Arrhenius equation k = Ae^(−Eₐ/RT) shows rates rise with temperature; catalysts lower Eₐ."},{"t":"p","text":"Equilibrium: K = [products]^coefficients ÷ [reactants]^coefficients (pure solids and liquids are left out). Q < K → forward; Q > K → reverse. Le Châtelier: a stressed equilibrium shifts to relieve the stress. ICE tables solve for equilibrium concentrations."},{"t":"ex","problem":"A first-order reaction has k = 0.0693 s⁻¹. Find its half-life.","steps":["t½ = 0.693 ÷ 0.0693"],"answer":"10 s"},{"t":"lab","kind":"lab","title":"Second-order decomposition of NO₂","aim":"Follow the concentration of NO₂ as it decomposes (2NO₂ → 2NO + O₂) and test which plot is linear.","sets":[{"name":"t","start":100,"label":"Time (s)","min":0,"max":600,"step":10},{"name":"kk","start":0.5,"label":"Rate constant k (M⁻¹ s⁻¹)","min":0.1,"max":2,"step":0.1}],"outs":[{"name":"A","expr":"1/(1/0.1 + kk*t)","label":"[NO₂] (M)"},{"name":"inv","expr":"1/A","label":"1/[NO₂] (M⁻¹)"},{"name":"lnA","expr":"ln(A)","label":"ln[NO₂]"}],"steps":["Record [NO₂], ln[NO₂] and 1/[NO₂] every 100 s.","Which quantity changes by the same amount each interval?"],"noise":1,"result":"1/[NO₂] vs t is a straight line with slope k, so the reaction is second order. For second-order reactions the half-life gets longer as the concentration falls, unlike first-order reactions.","plot":{"x":"t","y":"inv"}}]},{"say":"Proton transfers and electron transfers drive much of chemistry, from blood to batteries.","blocks":[{"t":"key","text":"Brønsted–Lowry acids donate H⁺; bases accept it. pH = −log[H⁺]; pH + pOH = 14 at 25 °C. Weak acids use Kₐ; Kₐ × K_b = K_w. Buffers (weak acid + conjugate base) resist pH change: pH = pKₐ + log([A⁻]/[HA]). Titration curves show equivalence points."},{"t":"p","text":"Redox: OIL RIG (oxidation is loss, reduction is gain). Galvanic cells: oxidation at the anode, reduction at the cathode; E°cell = E°cathode − E°anode, positive for spontaneous reactions. ΔG° = −nFE°. Electrolysis uses electricity to drive non-spontaneous reactions."},{"t":"ex","problem":"Find the pH of 0.001 M HCl.","steps":["Strong acid: [H⁺] = 1 × 10⁻³"],"answer":"pH 3"}]}]];
export default text;
